import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';

const SLUG = "ovo";

export class OvoGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "OVO Wallet",
      slug: "ovo",
      version: '1.0.0',
      description: "OVO Wallet payment gateway integration for OwnPay",
      author: 'OwnPay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: [],
      capabilities: ["verification"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "secret_key", label: "Xendit Secret Key", type: "password" as const, required: true },
    ];
  }

  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const secretKey = String(credentials["secret_key"] ?? '');
    const trxId = (params.trx_id ?? '');
    const amount = Math.trunc(Number((params.amount ?? '')));
    const redirectUrl = (params.redirect_url ?? '');
    const payload: Record<string, unknown> = { ["reference_id"]: trxId, ["currency"]: "IDR", ["amount"]: amount, ["checkout_method"]: "ONE_TIME_PAYMENT", ["channel_code"]: "ID_OVO", ["channel_properties"]: { ["mobile_number"]: "+6281234567890", ["success_redirect_url"]: redirectUrl } };
    const res = await gwJson({
      url: "https://api.xendit.co/ewallets/charges",
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["Authorization"]: `Basic ${btoa(`${String(secretKey)}:`)}` },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    const actions = ((d) as Record<string, unknown>)["actions"] ?? {};
    const desktopUrl = String(((actions) as Record<string, unknown>)["desktop_web_checkout_url"] ?? '');
    const checkoutUrl = (String(desktopUrl) !== String("")) ? (desktopUrl) : (redirectUrl);
    const sessionId = String(((d) as Record<string, unknown>)["id"] ?? '');
    return {
          redirect_url: (checkoutUrl || undefined) as string | undefined,
          session_id: (sessionId || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["charge_id"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const secretKey = String(credentials["secret_key"] ?? '');
    const res = await gwJson({
      url: `https://api.xendit.co/ewallets/charges/${String(cb["charge_id"])}`,
      method: 'GET',
      headers: { ["Authorization"]: `Basic ${btoa(`${String(secretKey)}:`)}` },
      timeoutMs: 10000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const ok = String(((d) as Record<string, unknown>)["status"]) === String("SUCCEEDED");
    return {
          success: ok,
          gateway_trx_id: String(((cb) as Record<string, unknown>)["charge_id"] ?? ''),
          amount: (String(((d) as Record<string, unknown>)["charge_amount"] ?? '') || null) as string | null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
          trx_id: String(((d) as Record<string, unknown>)["reference_id"] ?? ''),
        };
  }

  async verifyWebhook(_input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    // PORT-SECURITY: upstream accepted these webhooks without a signature
    // check (stub / header-presence only). Ported FAIL-CLOSED: unsigned
    // events are rejected. Payments complete via the signed checkout
    // callback + server-side verify() instead.
    return false;
  }
}
